// Generated by scripts/build-hunt-grass-tiles-20261125.py: which open tiles of the grass
// maps are grass (not dirt paths, water, plateaus or props), for ground contact tufts.
export const HUNT_GRASS_TILE_BITS = Object.freeze({
  hm01: '',
  hm02: '',
  hm03: '',
  hm04: ''
});

const decoded = new Map();
/** True when tile (x, y) of the map is grass; false off the map or for maps without data. */
export function huntGrassTile(mapKey, x, y) {
  const data = HUNT_GRASS_TILE_BITS[mapKey];
  if (!data || !Number.isInteger(x) || !Number.isInteger(y) || x < 0 || y < 0 || x >= 180 || y >= 180) return false;
  let bytes = decoded.get(mapKey);
  if (!bytes) { bytes = Uint8Array.from(atob(data), c => c.charCodeAt(0)); decoded.set(mapKey, bytes); }
  const i = y * 180 + x;
  return ((bytes[i >> 3] >> (i & 7)) & 1) === 1;
}
